#!/usr/bin/env python3

# ============================================================
# Compiled Cython single-file application
#
# Target:
#   OS           : android
#   Python       : 3.11
#   Architecture : aarch64
#
# The compiled native extension is embedded below.
# ============================================================

import base64
import hashlib
import importlib.util
import os
import shutil
import sys
import tempfile


MODULE_NAME = 'pydroid_311_native'
NATIVE_NAME = 'pydroid_311_native.cpython-311.so'

EXPECTED_SHA256 = '140376c2ae41b048ad63e8b2960c96c7f087937304ff70963ec7d38bc2db8476'

PAYLOAD = """

"""


def main():
    # Check the Python major/minor version.
    expected = '3.11'

    current = (
        f"{sys.version_info.major}."
        f"{sys.version_info.minor}"
    )

    if current != expected:
        print()
        print("This protected file was built for Python " + expected)
        print("Current Python: " + current)
        print()
        sys.exit(1)

    # Decode native module.
    try:
        binary = base64.b64decode(
            PAYLOAD.encode("ascii")
        )
    except Exception as exc:
        print("Failed to decode native payload:")
        print(exc)
        sys.exit(1)

    # Integrity check.
    digest = hashlib.sha256(binary).hexdigest()

    if digest != EXPECTED_SHA256:
        print("Native payload integrity check failed.")
        sys.exit(1)

    # Extract to a temporary directory.
    temp_dir = tempfile.mkdtemp(
        prefix="cython_runtime_"
    )

    native_path = os.path.join(
        temp_dir,
        NATIVE_NAME
    )

    try:
        with open(native_path, "wb") as f:
            f.write(binary)

        # The extension filename contains the ABI information,
        # so Python can load the correct native module.
        spec = importlib.util.spec_from_file_location(
            MODULE_NAME,
            native_path,
        )

        if spec is None or spec.loader is None:
            raise RuntimeError(
                "Unable to create module specification."
            )

        module = importlib.util.module_from_spec(
            spec
        )

        sys.modules[MODULE_NAME] = module

        spec.loader.exec_module(module)

    except Exception as exc:
        print()
        print("Failed to start protected application.")
        print("Reason:", exc)
        print()
        sys.exit(1)

    finally:
        # Native libraries may still be loaded from this path.
        # On Windows the file can remain locked, while on Linux/
        # Android cleanup usually succeeds.
        try:
            shutil.rmtree(temp_dir)
        except Exception:
            pass


if __name__ == "__main__":
    main()
